person.Email = "  Ada@Example.com ";

Console.WriteLine(person.Name);
Console.WriteLine(person.Email);
Console.WriteLine(person.AgeIn(2026));
Console.WriteLine(person.Initial);

// person.Name = "Grace";   does not compile: init-only after construction
// new Person();            does not compile: Name is required

class Person
{
    private string _email = "";

    public required string Name { get; init; }
    public int BirthYear { get; init; }

    public string Email
    {
        get => _email;
        set => _email = value.Trim().ToLowerInvariant();
    }

    public char Initial => Name[0];

    public int AgeIn(int year) => year - BirthYear;
}

