object?[] inputs = [0, 7, -3, "hello", "", null, 2.5];

foreach (object? input in inputs)
{
    Console.WriteLine(Classify(input));
}

string Classify(object? value) => value switch
{
    null => "nothing",
    0 => "zero",
    int n when n < 0 => $"negative {n}",
    int n => $"positive {n}",
    "" => "empty string",
    string s => $"text \"{s}\"",
    _ => $"other ({value})",
};

List<Order> orders =
[
    new Order("Ada", 120m, IsMember: true),
    new Order("Ken", 60m, IsMember: false),
    new Order("Grace", 300m, IsMember: false),
    new Order("Mei", 20m, IsMember: false),
];

foreach (var order in orders)
{
    string shipping = order switch
    {
        { IsMember: true } => "free (member)",
        { Total: >= 100m } => "free",
        { Total: >= 50m and < 100m } => "reduced",
        _ => "standard",
    };
    Console.WriteLine($"{order.Customer}: {shipping}");
}

record Order(string Customer, decimal Total, bool IsMember);

